<span class="line"><span style="color:#C792EA;">const</span><span style="color:#BABED8;"> requestMethod </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">get</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">;</span></span>
