<span class="line"><span style="color:#89DDFF;">  @</span><span style="color:#82AAFF;">Get</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/:id</span><span style="color:#89DDFF;">&quot;</span><span style="color:#BABED8;">)</span></span>
